Context {fx : PropExec.FPState}.

#[using="Type"] Theorem art_free3P :
  forall (Q : list aev -> machine_state -> Prop) (log : list aev) regs (M0 rom : word -> option byte) (raw0 : word)
         (S HI p q16 n qr b1 tp key tsd ctx t spb ris qs km l2 blk top bot L B wB cntB bszB bytes : Z) (kb : nat) (Dz : list (list Z)) (Kz : list Z) (ia inited : bool) (cl : art_cls) (parr mb ms f1 f2 : Z) (bl : list (Z * Z)) (idx : nat),
    let c := t + 80 in
    let ca := t + 208 in
    let b := spb + 24 * 2 ^ 32 + 16 * art_ca_cptr 24 cl in
    let newb := art_enq_newb L cntB in
    let bytes' := bytes + n + (if newb then 8192 else 0) in
